<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api} from '../api'
const data=ref<any>(null),draft=ref<any>(null),error=ref(''),notice=ref(''),busy=ref(false)
const projects=ref<any[]>([]),selectedProfile=ref(''),profile=ref<any>(null),projectIds=ref('')
async function load(){try{data.value=await api.get('/api/audio/settings');draft.value=structuredClone(data.value.limits);projects.value=(await api.get('/api/articles?limit=200')).articles||[]}catch(e:any){error.value=e.message}}
async function save(){busy.value=true;error.value='';try{await api.put('/api/audio/limits',draft.value);notice.value='累计额度已保存，已发送与未知请求仍计入额度';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function inventory(){busy.value=true;error.value='';try{const result=await api.post('/api/audio/inventory');notice.value=result.state==='confirmed'?`已读取 ${result.voices.length} 个已有音色`:result.error||'查询待确认';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function edit(){const p=data.value.voices.find((p:any)=>p.id===selectedProfile.value);if(!p){profile.value=null;return}profile.value={provider:p.provider,voice_id:p.voice_id,name:p.name,authorization:p.authorization,enabled:!!p.enabled,projects:p.projects};projectIds.value=p.projects.join(',')}
async function saveProfile(){busy.value=true;error.value='';try{await api.put('/api/audio/voices/'+selectedProfile.value,{...profile.value,projects:projectIds.value.split(',').map(s=>s.trim()).filter(Boolean)});notice.value='声音档案已更新，旧音频保留原始参数';await load();edit()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="panel p-5 space-y-4" aria-label="音频服务与额度"><h2 class="font-semibold">音频服务与额度</h2><p v-if="error" role="alert" class="text-red-700">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="data && draft"><p>MiniMax 密钥：{{data.key_set?'已配置':'未配置'}} · 默认已有音色：{{data.default_voice_id||'未设置'}}</p><p class="text-xs text-ink-400">密钥在服务端配置。仅查询/复用已有音色，不提供克隆创建、样本上传或远端删除。</p><div class="grid grid-cols-1 md:grid-cols-2 gap-4"><label>累计真实请求上限<input aria-label="累计真实请求上限" type="number" v-model.number="draft.max_requests" min="0" max="10000" /></label><label>累计发送字符上限<input aria-label="累计发送字符上限" type="number" v-model.number="draft.max_chars" min="0" max="1000000" /></label><label>累计估算金额上限（元，留空不限）<input type="number" v-model.number="draft.max_estimated_cost" min="0" step="0.1" @change="draft.max_estimated_cost=draft.max_estimated_cost===''?null:draft.max_estimated_cost" /></label><label>每万字符费率（元，未核实留空）<input type="number" v-model.number="draft.rate_per_10k" min="0" step="0.1" @change="draft.rate_per_10k=draft.rate_per_10k===''?null:draft.rate_per_10k" /></label><label>费率对应模型<select v-model="draft.rate_model"><option v-for="model in data.capabilities.models" :key="model">{{model}}</option></select></label><label>费率来源<input v-model="draft.rate_source" placeholder="当前账号账单或官方费率链接" /></label><label>费率生效时间<input v-model="draft.rate_effective" placeholder="YYYY-MM-DD" /></label></div><p class="text-xs text-ink-400">费用未核实会明确标记待确认。已发送、失败和响应未知请求计入累计额度；页面刷新与服务重启不重置计数。</p><button class="border rounded px-3 py-2" @click="save" :disabled="busy">保存音频预算</button><p>全部项目：已发送 {{data.ledger.sent_requests}} 次 / {{data.ledger.sent_chars}} 字符 · 预留 {{data.ledger.reserved_requests}} 次</p><details><summary>已有音色清单（只读缓存）</summary><button @click="inventory" class="border rounded px-3 py-2 my-3" :disabled="busy">{{data.inventory?'读取已缓存的查询结果':'查询一次已有音色'}}</button><p v-if="data.inventory">查询状态：{{data.inventory.state}} · 查询次数：{{data.inventory.attempts}}</p><p v-for="v in data.inventory?.voices||[]" :key="v.voice_id">{{v.name}} · {{v.voice_id}}</p></details><details><summary>声音档案与可用项目</summary><label class="mt-3">已登记档案<select v-model="selectedProfile" @change="edit"><option value="">选择档案</option><option v-for="v in data.voices" :key="v.id" :value="v.id">{{v.name}} · {{v.voice_id}}</option></select></label><div v-if="profile" class="space-y-3 mt-3"><label>显示名<input v-model="profile.name" /></label><label>已有 voice ID<input v-model="profile.voice_id" /></label><label>授权说明<textarea v-model="profile.authorization" /></label><label>允许使用的项目 ID（逗号分隔）<input v-model="projectIds" /></label><label><input type="checkbox" v-model="profile.enabled" />启用档案</label><button @click="saveProfile" class="border rounded px-3 py-2" :disabled="busy">保存声音档案</button><details><summary>项目 ID 参考</summary><p v-for="p in projects" :key="p.id">{{p.title}} · {{p.id}}</p></details></div></details></template></section></template>
<style scoped>label{display:flex;flex-direction:column;gap:6px;font-size:13px}input:not([type=checkbox]),select,textarea{border:1px solid var(--rule,#ddd);padding:8px;border-radius:6px;background:var(--surface,#fff);color:var(--text);width:100%}input[type=checkbox]{width:auto}summary{cursor:pointer}button:disabled{opacity:.5}</style>
